# --- Explorer: any series, any measure, any frequency ------------------------

mod_explorer_ui <- function(id) {
  ns <- NS(id)
  layout_sidebar(
    sidebar = sidebar(
      width = 330, open = "open",
      uiOutput(ns("items_ui")),
      uiOutput(ns("hl_ui")),
      radioButtons(ns("freq"), "Frequency",
                   c("Annual" = "annual", "Quarterly" = "quarterly", "Monthly" = "monthly"), inline = TRUE),
      selectInput(ns("measure"), "Measure", MEASURES),
      uiOutput(ns("years_ui")),
      checkboxInput(ns("target"), "Add the budget (annual) or programme (monthly) target", FALSE),
      radioButtons(ns("layout"), "Layout", c("One chart" = "single", "Small multiples" = "facet"),
                   inline = TRUE),
      note("Shares of GDP are annual only. Monthly and quarterly shares are taken against ",
           "revenue or spending in the same period. 2026 has months only, no full year yet.")
    ),
    card(
      full_screen = TRUE,
      card_header("Series explorer"),
      card_body(girafeOutput(ns("plot"), height = "640px")),
      card_footer(downloadButton(ns("dl"), "Download this selection (CSV)"))
    )
  )
}

mod_explorer_server <- function(id, dat) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    output$items_ui <- renderUI({
      selectInput(ns("items"), "Series", multiple = TRUE, choices = series_choices(dat()),
                  selected = c("total_revenue_grants", "total_expenditure"))
    })
    output$hl_ui <- renderUI({
      req(input$items)
      selectInput(ns("hl"), "Highlight", choices = stats::setNames(input$items, series_name(dat(), input$items)),
                  selected = input$items[1])
    })
    output$years_ui <- renderUI({
      yrs <- range(dat()$annual$year, dat()$periodic$year)
      year_slider(ns("years"), yrs[1]:yrs[2])
    })

    # % of GDP only exists for annual data
    observeEvent(input$freq, {
      ch <- if (input$freq == "annual") MEASURES else MEASURES[MEASURES != "gdp"]
      sel <- if (isTRUE(input$measure %in% ch)) input$measure else "bn"
      updateSelectInput(session, "measure", choices = ch, selected = sel)
    }, ignoreInit = TRUE)

    plot_data <- reactive({
      req(input$items, input$years, input$measure)
      get_series(dat(), input$items, input$measure, input$freq) |>
        dplyr::filter(.data$year >= input$years[1], .data$year <= input$years[2])
    })

    target_data <- reactive({
      if (!isTRUE(input$target) || input$measure %in% c("growth") || is.null(input$hl)) return(NULL)
      fig <- if (input$freq == "annual") "budget" else "programme"
      out <- get_series(dat(), input$hl, input$measure, input$freq, figure = fig)
      if (input$freq == "annual") {
        rev <- get_series(dat(), input$hl, input$measure, "annual", figure = "revised_budget")
        out <- dplyr::bind_rows(rev, dplyr::anti_join(out, rev, by = "year"))
      }
      out |> dplyr::filter(.data$year >= input$years[1], .data$year <= input$years[2])
    })

    output$plot <- renderGirafe({
      df <- plot_data()
      validate(need(nrow(df) > 0, "No data for that selection. Shares of GDP need the annual frequency."))
      unit <- MEASURE_UNIT[[input$measure]]
      hl <- series_name(dat(), input$hl %||% input$items[1])
      sub <- paste0(tools::toTitleCase(input$freq), " outturns, ", MEASURE_LAB[[input$measure]],
                    ", ", df$period[which.min(df$t)], " to ", df$period[which.max(df$t)])
      tg <- target_data()
      if (!is.null(tg) && nrow(tg) > 0) sub <- paste0(sub, ". Dashed: ", if (input$freq == "annual")
        "revised budget (or budget)" else "programme", " for ", hl)
      gf(line_chart(df, highlight = hl, title = "Ghana's Public Finances, Series by Series",
                    subtitle = sub, unit = unit, digits = if (unit == "bn") 1 else 1,
                    zero_line = input$measure == "growth" || any(df$value < 0),
                    facet = identical(input$layout, "facet"),
                    label_ends = input$freq == "annual" || length(unique(df$item)) <= 3,
                    target = tg),
         height = 6.4)
    })

    output$dl <- downloadHandler(
      filename = \() paste0("ghana_fiscal_", input$freq, "_", input$measure, "_", Sys.Date(), ".csv"),
      content = \(f) readr::write_csv(plot_data() |> dplyr::select("period", "item", "series_id", "value"), f)
    )
  })
}

# --- Overview: one budget year at a glance, on bslib value boxes ------------

mod_overview_ui <- function(id) {
  ns <- NS(id)
  tagList(
    layout_columns(
      col_widths = c(4, 8),
      card(
        card_header("Budget year"),
        card_body(
          uiOutput(ns("year_ui")),
          note("Pick a year and the whole page rewrites itself. Ratios to GDP use a consistent ",
               "World Bank GDP series, not the GDP in each year's workbook.")
        )
      ),
      card(
        card_header("The year in a paragraph"),
        card_body(uiOutput(ns("story")))
      )
    ),
    uiOutput(ns("boxes")),
    layout_columns(
      col_widths = c(6, 6),
      card(full_screen = TRUE, card_header("Revenue against spending"),
           card_body(girafeOutput(ns("p_revexp"), height = "430px"))),
      card(full_screen = TRUE, card_header("The deficit, year by year"),
           card_body(girafeOutput(ns("p_deficit"), height = "430px")))
    )
  )
}

mod_overview_server <- function(id, dat, parent = NULL) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    output$year_ui <- renderUI({
      yrs <- full_years(dat())
      selectInput(ns("year"), "Year", choices = rev(yrs), selected = max(yrs), width = "100%")
    })

    # every ratio the page needs, for all years
    ratios <- reactive({
      w <- annual_wide(dat())
      ex <- execution(dat(), "capex") |> dplyr::select("year", capex_exec = "value")
      w |>
        dplyr::left_join(ex, by = "year") |>
        dplyr::transmute(
          year = .data$year,
          rev_gdp = 100 * .data$total_revenue_grants / .data$gdp,
          exp_gdp = 100 * .data$total_expenditure / .data$gdp,
          def_gdp = -100 * .data$overall_balance_cash_disc / .data$gdp,
          int_rev = 100 * .data$interest / .data$total_revenue_grants,
          comp_rev = 100 * .data$compensation / .data$total_revenue_grants,
          capex_gdp = 100 * .data$capex / .data$gdp,
          fixed_rev = 100 * (.data$compensation + .data$interest + .data$grants_other_gov) /
            .data$total_revenue_grants,
          capex_exec = .data$capex_exec,
          revenue_bn = .data$total_revenue_grants / 1e9
        )
    })

    snap <- reactive({
      req(input$year)
      r <- ratios(); y <- as.integer(input$year)
      now <- r[r$year == y, ]; prev <- r[r$year == y - 1, ]
      hist <- r[r$year <= y, ]
      list(year = y, now = now, prev = prev, hist = hist)
    })

    vb <- function(title, value, context, icon, colour, spark = NULL, link_id = NULL) {
      value_box(
        title = title, value = value,
        showcase = tile_icon(icon, 30), showcase_layout = showcase_left_center(),
        theme = value_box_theme(bg = colour, fg = "#FFFFFF"), height = "180px",
        if (!is.null(context)) p(class = "vb-context", context),
        if (!is.null(link_id)) p(class = "vb-link", actionLink(ns(link_id), "View details")),
        if (!is.null(spark)) div(class = "vb-spark", spark)
      )
    }
    v1 <- function(x, fmt = "%.1f%%") if (length(x) != 1 || is.na(x)) "n/a" else sprintf(fmt, x)
    chip <- function(k) {
      s <- snap()
      if (nrow(s$prev) == 0) return(NULL)
      delta_chip(s$now[[k]], s$prev[[k]])
    }
    spk <- function(k) sparkline_svg(utils::tail(snap()$hist[[k]], 12), "#FFFFFF", full = TRUE)

    output$boxes <- renderUI({
      s <- snap(); n <- s$now
      validate(need(nrow(n) == 1, "No outturn for that year."))
      tagList(
        layout_column_wrap(
          width = 1/4, gap = "1rem", heights_equal = "row",
          vb("Revenue and grants", v1(n$rev_gdp), paste0("of GDP. ", chip("rev_gdp") %||% ""),
             "coins", TILE[["navy"]], spk("rev_gdp"), "go1"),
          vb("Total spending", v1(n$exp_gdp), paste0("of GDP. ", chip("exp_gdp") %||% ""),
             "bars", TILE[["slate"]], spk("exp_gdp"), "go2"),
          vb("Overall deficit", v1(n$def_gdp),
             if (is.na(n$def_gdp)) "cash basis, from 2011" else paste0("of GDP. ", chip("def_gdp") %||% ""),
             "scale", TILE[["steel"]], spk("def_gdp"), "go3"),
          vb("Interest bill", v1(n$int_rev), paste0("of revenue. ", chip("int_rev") %||% ""),
             "clock", TILE[["rust"]], spk("int_rev"), "go4")
        ),
        div(style = "height:1rem;"),
        layout_column_wrap(
          width = 1/4, gap = "1rem", heights_equal = "row",
          vb("Wage bill", v1(n$comp_rev), paste0("of revenue. ", chip("comp_rev") %||% ""),
             "people", TILE[["bronze"]], spk("comp_rev"), "go5"),
          vb("Wages, interest and transfers", v1(n$fixed_rev),
             if (is.na(n$fixed_rev)) "shown from 2013" else "of revenue, before any project",
             "bolt", TILE[["brick"]], spk("fixed_rev"), "go6"),
          vb("Capital spending", v1(n$capex_gdp), paste0("of GDP. ", chip("capex_gdp") %||% ""),
             "build", TILE[["green"]], spk("capex_gdp"), "go7"),
          vb("Capex against budget", v1(n$capex_exec, "%.0f%%"), "of the budgeted amount was spent",
             "target", TILE[["charcoal"]], NULL, "go8")
        )
      )
    })

    if (!is.null(parent)) {
      jumps <- c(go1 = "Explorer", go2 = "Explorer", go3 = "Explorer", go4 = "Pressures",
                 go5 = "Pressures", go6 = "Pressures", go7 = "Pressures", go8 = "Budget vs actual")
      lapply(names(jumps), function(k) {
        observeEvent(input[[k]], nav_select("tab", jumps[[k]], session = parent), ignoreInit = TRUE)
      })
    }

    output$story <- renderUI({
      s <- snap(); n <- s$now
      validate(need(nrow(n) == 1, ""))
      txt <- sprintf(
        paste0("In %d the government collected %.1f%% of GDP in revenue and grants and spent %.1f%%. ",
               "Interest took %.0f%% of every cedi that came in, and the wage bill %.0f%%. ",
               "Capital spending came to %.1f%% of GDP"),
        s$year, n$rev_gdp, n$exp_gdp, n$int_rev, n$comp_rev, n$capex_gdp)
      if (!is.na(n$capex_exec)) txt <- paste0(txt, sprintf(", %.0f%% of what was budgeted.", n$capex_exec))
      else txt <- paste0(txt, ".")
      if (!is.na(n$def_gdp)) txt <- paste0(txt, sprintf(" The overall deficit was %.1f%% of GDP.", n$def_gdp))
      if (!is.na(n$fixed_rev)) {
        txt <- paste0(txt, sprintf(
          " Wages, interest and statutory transfers together came to %.0f%% of revenue%s",
          n$fixed_rev, if (n$fixed_rev >= 100) ", more than the government collected." else "."))
      }
      if (s$year %in% ELECTION_YEARS) txt <- paste0(txt, " It was an election year.")
      div(class = "story", txt)
    })

    output$p_revexp <- renderGirafe({
      s <- snap()
      df <- ratios() |>
        dplyr::transmute(t = .data$year, period = as.character(.data$year),
                         Revenue = .data$rev_gdp, Spending = .data$exp_gdp) |>
        tidyr::pivot_longer(c("Revenue", "Spending"), names_to = "item", values_to = "value") |>
        dplyr::filter(!is.na(.data$value))
      p <- line_chart(df, highlight = "Revenue", title = "Revenue Is Stuck; Spending Is Not",
                      subtitle = "Total revenue and grants against total spending, % of GDP", unit = "%") +
        ggplot2::geom_vline(xintercept = s$year, colour = RUST, alpha = 0.35, linewidth = 6)
      gf(p, height = 4.6)
    })

    output$p_deficit <- renderGirafe({
      s <- snap()
      df <- ratios() |>
        dplyr::filter(!is.na(.data$def_gdp)) |>
        dplyr::transmute(t = .data$year, period = as.character(.data$year), value = .data$def_gdp,
                         hl = .data$year %in% ELECTION_YEARS)
      p <- col_chart(df, title = "Election Years Push the Deficit Up",
                     subtitle = "Overall deficit, cash basis incl. discrepancy, % of GDP",
                     unit = "%", digits = 1, hl_label = "Election year", other_label = "Other years")
      if (s$year %in% df$t) {
        p <- p + ggplot2::annotate("point", x = s$year, y = 0, shape = 17, size = 4, colour = DARK)
      }
      gf(p, height = 4.6)
    })
  })
}

# --- Revenue mix: which taxes carry the budget -------------------------------

TAX_SHORT <- c(taxes_income_property = "Income and property", taxes_goods_services = "Goods and services",
               intl_trade_taxes = "Trade", personal_income_tax = "Personal income tax",
               company_taxes = "Company tax", company_taxes_oil = "Company tax on oil", vat = "VAT",
               nhil = "NHIL", getfund_levy = "GETFund levy", excises = "Excise duties",
               cst = "Communication tax", e_levy = "E-levy", covid_levy = "COVID-19 levy",
               import_duties = "Import duties", export_duties = "Export duties")

TAX_SETS <- list(
  broad = c("taxes_income_property", "taxes_goods_services", "intl_trade_taxes"),
  detail = c("personal_income_tax", "company_taxes", "company_taxes_oil", "vat", "nhil", "getfund_levy",
             "excises", "cst", "e_levy", "covid_levy", "import_duties", "export_duties")
)

mod_revenue_ui <- function(id) {
  ns <- NS(id)
  layout_sidebar(
    sidebar = sidebar(
      width = 330, open = "open",
      radioButtons(ns("set"), "Breakdown",
                   c("Three tax groups" = "broad", "Individual taxes" = "detail")),
      radioButtons(ns("view"), "Show",
                   c("Share of tax revenue" = "share", "% of GDP" = "gdp", "GH¢ billion" = "bn")),
      uiOutput(ns("years_ui")),
      note("2008-2012 use MoF's older Direct/Indirect classification. Some taxes appear on the ",
           "summary table only from the year they were introduced or first reported.")
    ),
    card(
      full_screen = TRUE,
      card_header("Where tax revenue comes from"),
      card_body(girafeOutput(ns("plot"), height = "620px")),
      card_footer(downloadButton(ns("dl"), "Download this selection (CSV)"))
    )
  )
}

mod_revenue_server <- function(id, dat) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns
    output$years_ui <- renderUI(year_slider(ns("years"), full_years(dat()), value = c(2013, max(full_years(dat())))))

    plot_data <- reactive({
      req(input$years, input$set, input$view)
      ids <- TAX_SETS[[input$set]]
      d <- dat()
      out <- if (input$view == "share") {
        a <- get_series(d, ids, "bn", "annual")
        tax <- get_series(d, "tax_revenue", "bn", "annual") |> dplyr::select("year", tax = "value")
        a |> dplyr::inner_join(tax, by = "year") |> dplyr::mutate(value = 100 * .data$value / .data$tax)
      } else {
        get_series(d, ids, input$view, "annual")
      }
      out |>
        dplyr::filter(.data$year >= input$years[1], .data$year <= input$years[2]) |>
        dplyr::mutate(item = unname(TAX_SHORT[.data$series_id]))
    })

    output$plot <- renderGirafe({
      df <- plot_data()
      validate(need(nrow(df) > 0, "No data for that selection."))
      unit <- if (input$view == "bn") "bn" else "%"
      sub <- switch(input$view, share = "Share of total tax revenue", gdp = "% of GDP", bn = "GH¢ billion")
      if (input$set == "broad") {
        gf(line_chart(df, highlight = "Income and property",
                      title = "Which Taxes Carry Ghana's Budget", subtitle = sub, unit = unit),
           height = 6.2)
      } else {
        top <- df |> dplyr::filter(.data$year == max(.data$year)) |> dplyr::slice_max(.data$value, n = 1)
        gf(line_chart(df, highlight = top$item[1], title = "Ghana's Taxes, One by One",
                      subtitle = paste0(sub, "; small multiples"), unit = unit, facet = TRUE),
           height = 6.6)
      }
    })

    output$dl <- downloadHandler(
      filename = \() paste0("ghana_tax_mix_", input$view, "_", Sys.Date(), ".csv"),
      content = \(f) readr::write_csv(plot_data() |> dplyr::select("year", "item", "series_id", "value"), f)
    )
  })
}

# --- Year to date: this year against the same months of earlier years -------

YTD_DEFAULT <- c("tax_revenue", "compensation", "interest", "capex")

mod_ytd_ui <- function(id) {
  ns <- NS(id)
  layout_sidebar(
    sidebar = sidebar(
      width = 330, open = "open",
      uiOutput(ns("items_ui")),
      uiOutput(ns("month_ui")),
      uiOutput(ns("years_ui")),
      note("Nominal cedis. Compares January to the chosen month in each year, so a partial ",
           "year is set against the same months before it.")
    ),
    card(
      full_screen = TRUE,
      card_header("Year to date"),
      card_body(girafeOutput(ns("plot"), height = "600px")),
      card_footer(downloadButton(ns("dl"), "Download this selection (CSV)"))
    )
  )
}

mod_ytd_server <- function(id, dat) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns
    latest <- reactive(dat()$latest_date)

    output$items_ui <- renderUI({
      selectInput(ns("items"), "Series", multiple = TRUE, choices = series_choices(dat(), c("Revenue", "Spending")),
                  selected = YTD_DEFAULT)
    })
    output$month_ui <- renderUI({
      m <- as.integer(format(latest(), "%m"))
      selectInput(ns("month"), "January to", choices = stats::setNames(1:12, month.name), selected = m)
    })
    output$years_ui <- renderUI({
      y <- as.integer(format(latest(), "%Y"))
      yrs <- sort(unique(dat()$periodic$year))
      selectInput(ns("years"), "Years", choices = rev(yrs), multiple = TRUE, selected = (y - 2):y)
    })

    ytd <- reactive({
      req(input$items, input$month, input$years)
      ytd_totals(dat(), input$items, as.integer(input$month), as.integer(input$years))
    })

    output$plot <- renderGirafe({
      df <- ytd()
      validate(need(nrow(df) > 0, "No complete months for that selection."))
      yrs <- sort(unique(df$year))
      df <- df |> dplyr::mutate(grp = factor(.data$year, levels = yrs),
                                item = factor(.data$item, levels = unique(series_name(dat(), input$items))))
      last <- max(yrs); prev <- last - 1
      chg <- df |>
        dplyr::group_by(.data$item) |>
        dplyr::summarise(top = max(.data$value),
                         lab = if (all(c(last, prev) %in% .data$year))
                           sprintf("%+.0f%% vs %d", 100 * (.data$value[.data$year == last] /
                                                             .data$value[.data$year == prev] - 1), prev)
                         else "", .groups = "drop")
      m <- as.integer(input$month)
      span <- if (m == 1) "January" else paste0("January to ", month.name[m])
      gf(group_chart(df, title = paste0(last, " So Far, Against Earlier Years"),
                     subtitle = paste0(span, ", GH¢ billion, provisional outturns"),
                     unit = "bn", chg = chg),
         height = 6)
    })

    output$dl <- downloadHandler(
      filename = \() paste0("ghana_ytd_", Sys.Date(), ".csv"),
      content = \(f) readr::write_csv(ytd() |> dplyr::select("year", "item", "series_id", ghs_bn = "value"), f)
    )
  })
}
